format ELF64

section '.data' writeable

; memory layout
stack_pos dq 0
stack_end dq 0
heap_base dq 0
heap_top dq 0
heap_end dq 0
cell_pos dq 0
cell_end dq 0
free_list dq 0

alloc_oom_msg db 'Runtime error: out of memory', 10
alloc_oom_len = $ - alloc_oom_msg
alloc_negative_msg db 'Runtime error: negative allocation size', 10
alloc_negative_len = $ - alloc_negative_msg
alloc_invalid_msg db 'Runtime error: invalid free', 10
alloc_invalid_len = $ - alloc_invalid_msg
alloc_double_msg db 'Runtime error: double free', 10
alloc_double_len = $ - alloc_double_msg

STACK_SIZE = 0x10000
CELL_CHUNK_SIZE = 0x10000
HEAP_GROW_SIZE = 0x100000

section '.text' executable

;
;
; allocator_init
;
;   INPUT: nothing
;   OUTPUT: nothing
allocator_init:
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame

    ; initialize the heap
    mov     rax, 12                    ; brk
    mov     rdi, 0                     ; increment = 0
    syscall
    mov     [heap_end], rax            ; save the end of the heap
    add     rax, 7
    and     rax, -8
    mov     [heap_top], rax            ; align the top of the heap

    ; allocate the stack 64K
    mov     rdi, STACK_SIZE
    call    heap_take
    mov     [stack_pos], rax           ; save the current position of the stack
    add     rax, STACK_SIZE
    mov     [stack_end], rax           ; save the end of the stack

    ; blocks and cell chunks come after the stack
    mov     [heap_base], rax
    mov     [cell_pos], rax
    mov     [cell_end], rax

    pop     rbp                        ; restore return address
    ret

;
;
; stack push addr
;
;   INPUT: rdi contains the int64 (pointer) that we add to the stack
;   OUTPUT: nothing
;
stack_push_addr:
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame

    mov     rsi, qword [stack_pos]
    mov     qword [rsi], rdi
    add     qword [stack_pos], 8

    pop     rbp                        ; restore return address
    ret

;
;
; stack push
;
;   INPUT: rdi contains the int64 (pointer) that we add to the stack
;   OUTPUT: nothing
;
stack_push:
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame

    mov     rax, qword [cell_pos]
    cmp     rax, qword [cell_end]
    jb      .push_cell

    push    rdi
    mov     rdi, CELL_CHUNK_SIZE
    call    heap_take                  ; start a new cell chunk
    pop     rdi
    lea     rsi, [rax + CELL_CHUNK_SIZE]
    mov     qword [cell_end], rsi

.push_cell:
    mov     qword [rax], rdi
    lea     rsi, [rax + 8]
    mov     qword [cell_pos], rsi

    mov     rsi, qword [stack_pos]
    mov     qword [rsi], rax
    add     qword [stack_pos], 8

    pop     rbp                        ; restore return address
    ret

;
;
; stack peek addr
;
;   INPUT: nothing
;   OUTPUT: rax contains the int64 (pointer) that we pop from the stack
;
stack_peek_addr:
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame

    mov     rax, qword [stack_pos]
    mov     rax, qword [rax - 8]

    pop     rbp                        ; restore return address
    ret

;
;
; stack peek
;
;   INPUT: nothing
;   OUTPUT: rax contains the int64 (pointer) that we pop from the stack
;
stack_peek:
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame

    mov     rax, qword [stack_pos]
    mov     rax, qword [rax - 8]
    mov     rax, qword [rax]

    pop     rbp                        ; restore return address
    ret

;
;
; stack pop addr
;
;   INPUT: nothing
;   OUTPUT: rax contains the int64 (pointer) that we pop from the stack
;
stack_pop_addr:
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame

    mov     rax, qword [stack_pos]
    mov     rax, qword [rax - 8]
    sub     qword [stack_pos], 8

    pop     rbp                        ; restore return address
    ret

;
;
; stack pop
;
;   INPUT: nothing
;   OUTPUT: rax contains the int64 (pointer) that we pop from the stack
;
stack_pop:
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame

    mov     rax, qword [stack_pos]
    mov     rax, qword [rax - 8]
    mov     rax, qword [rax]
    sub     qword [stack_pos], 8

    pop     rbp                        ; restore return address
    ret

;
;
; stack pick
;
;   INPUT: rdi contains the index
;   OUTPUT: rax contains the int64 (pointer) that we pick from the stack
;
stack_pick_addr:
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame

    mov     rax, qword [stack_pos]
    shl     rdi, 3 ; multiply index with 8
    sub     rax, rdi ; offset stack_pos with index*8
    mov     rax, qword [rax - 8]

    pop     rbp                        ; restore return address
    ret

;
;
; heap take
;
;   INPUT: rdi contains the size in bytes (multiple of 8)
;   OUTPUT: rax points to new memory at the top of the heap
;
heap_take:
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    push    rcx
    push    rdx
    push    rdi
    push    r11

    mov     rdx, qword [heap_top]
    add     rdx, rdi                   ; new top of the heap
    jc      alloc_oom
    cmp     rdx, qword [heap_end]
    jbe     .take_ok

    mov     rdi, rdx
    add     rdi, HEAP_GROW_SIZE - 1
    jc      alloc_oom
    and     rdi, -HEAP_GROW_SIZE       ; new end of the heap
    mov     rax, 12                    ; brk
    syscall
    cmp     rax, rdi                   ; brk returns the old end on failure
    jb      alloc_oom
    mov     qword [heap_end], rax

.take_ok:
    mov     rax, qword [heap_top]
    mov     qword [heap_top], rdx

    pop     r11
    pop     rdi
    pop     rdx
    pop     rcx
    pop     rbp                        ; restore return address
    ret

;
;
; allocate
;
;   INPUT: rdi contains the size in bytes
;   OUTPUT: rax points to the newly allocated zeroed memory
;
;   A block has an 8 byte header with the block size and bit 0 set when
;   allocated. A free block keeps the next free block in its first 8 bytes.
;
allocate:
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    push    rcx
    push    rdx
    push    rsi
    push    rdi
    push    r8

    test    rdi, rdi
    js      alloc_negative
    add     rdi, 15
    and     rdi, -8                    ; block size with header
    cmp     rdi, 16
    jae     .alloc_sized
    mov     rdi, 16                    ; at least 8 bytes of memory
.alloc_sized:

    ; first fit in the free list
    xor     esi, esi                   ; previous free block
    mov     rax, qword [free_list]
.alloc_find:
    test    rax, rax
    jz      .alloc_fresh
    mov     rdx, qword [rax]
    cmp     rdx, rdi
    jae     .alloc_found
    mov     rsi, rax
    mov     rax, qword [rax + 8]
    jmp     .alloc_find

.alloc_found:
    mov     rcx, qword [rax + 8]       ; next free block
    sub     rdx, rdi
    cmp     rdx, 16
    jb      .alloc_whole
    lea     r8, [rax + rdi]            ; split the rest into a free block
    mov     qword [r8], rdx
    mov     qword [r8 + 8], rcx
    mov     rcx, r8
    jmp     .alloc_unlink
.alloc_whole:
    add     rdi, rdx                   ; use the whole free block
.alloc_unlink:
    test    rsi, rsi
    jz      .alloc_head
    mov     qword [rsi + 8], rcx
    jmp     .alloc_clear
.alloc_head:
    mov     qword [free_list], rcx
.alloc_clear:
    lea     rcx, [rax + 8]
    lea     rdx, [rax + rdi]
.alloc_clear_next:
    mov     qword [rcx], 0
    add     rcx, 8
    cmp     rcx, rdx
    jb      .alloc_clear_next
    jmp     .alloc_ok

.alloc_fresh:
    call    heap_take                  ; new memory is already zero

.alloc_ok:
    or      rdi, 1
    mov     qword [rax], rdi
    add     rax, 8

    pop     r8
    pop     rdi
    pop     rsi
    pop     rdx
    pop     rcx
    pop     rbp                        ; restore return address
    ret

;
;
; deallocate
;
;   INPUT: rdi points to memory from allocate, or is 0
;   OUTPUT: nothing
;
;   The free list is sorted by address. Adjacent free blocks are merged.
;
deallocate:
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    push    rax
    push    rcx
    push    rdx
    push    rsi
    push    rdi
    push    r8

    test    rdi, rdi
    jz      .free_done
    test    rdi, 7
    jnz     alloc_invalid_free
    sub     rdi, 8                     ; block header
    cmp     rdi, qword [heap_base]
    jb      alloc_invalid_free
    mov     rax, qword [heap_top]
    sub     rax, rdi                   ; bytes from the block to the heap top
    jb      alloc_invalid_free
    cmp     rax, 16
    jb      alloc_invalid_free
    mov     rdx, qword [rdi]
    mov     rcx, rdx
    and     rcx, -8                    ; block size
    cmp     rcx, 16
    jb      alloc_invalid_free
    cmp     rcx, rax
    ja      alloc_invalid_free
    test    rdx, 6
    jnz     alloc_invalid_free
    test    rdx, 1
    jz      alloc_double_free

    ; find the free blocks before and after the block
    xor     esi, esi                   ; previous free block
    mov     rax, qword [free_list]     ; next free block
.free_find:
    test    rax, rax
    jz      .free_check
    cmp     rax, rdi
    jae     .free_check
    mov     rsi, rax
    mov     rax, qword [rax + 8]
    jmp     .free_find

.free_check:
    test    rsi, rsi
    jz      .free_check_next
    mov     rdx, qword [rsi]
    add     rdx, rsi
    cmp     rdx, rdi
    ja      alloc_double_free          ; the block is inside a free block
.free_check_next:
    test    rax, rax
    jz      .free_merge_prev
    lea     rdx, [rdi + rcx]
    cmp     rdx, rax
    ja      alloc_invalid_free         ; the block overlaps a free block
    jb      .free_merge_prev
    add     rcx, qword [rax]           ; merge with the next free block
    mov     rax, qword [rax + 8]

.free_merge_prev:
    test    rsi, rsi
    jz      .free_head
    mov     rdx, qword [rsi]
    lea     r8, [rsi + rdx]
    cmp     r8, rdi
    jne     .free_after
    add     rdx, rcx                   ; merge with the previous free block
    mov     qword [rsi], rdx
    mov     qword [rsi + 8], rax
    jmp     .free_done
.free_after:
    mov     qword [rsi + 8], rdi
    jmp     .free_link
.free_head:
    mov     qword [free_list], rdi
.free_link:
    mov     qword [rdi], rcx
    mov     qword [rdi + 8], rax

.free_done:
    pop     r8
    pop     rdi
    pop     rsi
    pop     rdx
    pop     rcx
    pop     rax
    pop     rbp                        ; restore return address
    ret

;
;
; allocator errors write a message and exit with status 1
;
alloc_oom:
    mov     rsi, alloc_oom_msg
    mov     rdx, alloc_oom_len
    jmp     alloc_abort
alloc_negative:
    mov     rsi, alloc_negative_msg
    mov     rdx, alloc_negative_len
    jmp     alloc_abort
alloc_invalid_free:
    mov     rsi, alloc_invalid_msg
    mov     rdx, alloc_invalid_len
    jmp     alloc_abort
alloc_double_free:
    mov     rsi, alloc_double_msg
    mov     rdx, alloc_double_len
alloc_abort:
    mov     rax, 1                     ; write
    mov     rdi, 2                     ; stderr
    syscall
    mov     rax, 60                    ; exit
    mov     rdi, 1
    syscall

section '.data' writeable

stack_env dq 0

; Define some constants
loc_0 = 8
loc_1 = 16
loc_2 = 24
loc_3 = 32
loc_4 = 40
loc_5 = 48
loc_6 = 56
loc_7 = 64

arg_0 = 16
arg_1 = 24
arg_2 = 32
arg_3 = 40
arg_4 = 48
arg_5 = 56
arg_6 = 64
arg_7 = 72

; Define entry point
section '.text' executable
public _start
_start:
    ; Initialize the memory
    call allocator_init

    ; store argc on the stack
    mov     rdi, qword [rsp]
    call    stack_push

    ; store argv on the stack
    mov     rdi, rsp
    add     rdi, 8
    call    stack_push

    ; store env in stack_env
    mov     rax, qword [rsp]
    shl     rax, 3
    mov     rdi, rsp
    add     rdi, 8
    add     rdi, rax
    add     rdi, 8
    mov     qword [stack_env], rdi

    ; Call the main method
    call    func.0 ; main

    ; Exit the program
    call    stack_pop
    mov     rdi, rax
    mov     rax, 60
    syscall

section '.text' executable

;
;
; dup
;
;   INPUT: (a)
;   OUTPUT: (a, a)
func.1: ; dup
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_peek_addr
    mov     rdi, rax
    call    stack_push_addr

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; swp
;
;   INPUT: (a, b)
;   OUTPUT: (b, a)
func.2: ; swp
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    ; t0 <- A
    call    stack_pop_addr
    mov     qword [rbp - loc_0], rax

    ; t1 <- B
    call    stack_pop_addr
    mov     qword [rbp - loc_1], rax

    ; push A
    mov     rdi, [rbp - loc_0]
    call    stack_push_addr

    ; push B
    mov     rdi, [rbp - loc_1]
    call    stack_push_addr

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; rot
;
;   INPUT: (a, b, c)
;   OUTPUT: (b, c, a)
func.3: ; rot
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 32                    ; allocate 4 local variables

    ; (C B A) -> (B A C)

    ; t0 <- A
    call    stack_pop_addr
    mov     qword [rbp - loc_0], rax

    ; t1 <- B
    call    stack_pop_addr
    mov     qword [rbp - loc_1], rax

    ; t2 <- C
    call    stack_pop_addr
    mov     qword [rbp - loc_2], rax

    ; push B
    mov     rdi, [rbp - loc_1]
    call    stack_push_addr

    ; push A
    mov     rdi, [rbp - loc_0]
    call    stack_push_addr

    ; push C
    mov     rdi, [rbp - loc_2]
    call    stack_push_addr

    add     rsp, 32                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; rot4
;
;   INPUT: (a, b, c, d)
;   OUTPUT: (b, c, d, a)
func.4: ; rot4
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 32                    ; allocate 4 local variables

    ; (D C B A) -> (C B A D)

    ; t0 <- A
    call    stack_pop_addr
    mov     qword [rbp - loc_0], rax

    ; t1 <- B
    call    stack_pop_addr
    mov     qword [rbp - loc_1], rax

    ; t2 <- C
    call    stack_pop_addr
    mov     qword [rbp - loc_2], rax

    ; t3 <- D
    call    stack_pop_addr
    mov     qword [rbp - loc_3], rax

    ; push C
    mov     rdi, [rbp - loc_2]
    call    stack_push_addr

    ; push B
    mov     rdi, [rbp - loc_1]
    call    stack_push_addr

    ; push A
    mov     rdi, [rbp - loc_0]
    call    stack_push_addr

    ; push D
    mov     rdi, [rbp - loc_3]
    call    stack_push_addr

    add     rsp, 32                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; pop
;
;   INPUT: (a)
;   OUTPUT: ()
func.5: ; pop
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop_addr

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; pick
;
;   INPUT: (int)
;   OUTPUT: (ptr)
func.6: ; pick
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    mov     rdi, rax
    call    stack_pick_addr
    mov     rdi, rax
    call    stack_push

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; plus
;
;   INPUT: (int, int)
;   OUTPUT: (int)
func.7: ; +
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    push    rax

    call    stack_pop
    pop     rdi

    add     rdi, rax
    call    stack_push

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; sub
;
;   INPUT: (int, int)
;   OUTPUT: (int)
func.8: ; -
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    push    rax

    call    stack_pop
    mov     rdi, rax
    pop     rax

    sub     rdi, rax
    call    stack_push

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; mul
;
;   INPUT: (int, int)
;   OUTPUT: (int)
func.9: ; *
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    push    rax

    call    stack_pop
    pop     rdi

    mul     rdi
    mov     rdi, rax
    call    stack_push

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; div
;
;   INPUT: (int, int)
;   OUTPUT: (int)
func.10: ; /
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    push    rax

    call    stack_pop
    pop     rdi

    cqo
    idiv    rdi
    mov     rdi, rax
    call    stack_push

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; mod
;
;   INPUT: (int, int)
;   OUTPUT: (int)
func.11: ; %
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    push    rax

    call    stack_pop
    pop     rdi

    cqo
    idiv    rdi
    mov     rdi, rdx
    call    stack_push

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; and
;
;   INPUT: (int, int)
;   OUTPUT: (int)
func.12: ; &
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    push    rax

    call    stack_pop
    pop     rdi

    and     rdi, rax
    call    stack_push

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; or
;
;   INPUT: (int, int)
;   OUTPUT: (int)
func.13: ; |
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    push    rax

    call    stack_pop
    pop     rdi

    or      rdi, rax
    call    stack_push

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; xor
;
;   INPUT: (int, int)
;   OUTPUT: (int)
func.14: ; ^
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    push    rax

    call    stack_pop
    pop     rdi

    xor     rdi, rax
    call    stack_push

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; shr
;
;   INPUT: (int, int)
;   OUTPUT: (int)
func.15: ; >>
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    push    rax

    call    stack_pop
    pop     rcx

    sar     rax, cl
    mov     rdi, rax
    call    stack_push

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; shl
;
;   INPUT: (int, int)
;   OUTPUT: (int)
func.16: ; <<
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    push    rax

    call    stack_pop
    pop     rcx

    shl     rax, cl
    mov     rdi, rax
    call    stack_push

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; greater than
;
;   INPUT: (int, int)
;   OUTPUT: (bool)
func.17: ; >
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    push    rax

    call    stack_pop
    mov     rdi, rax
    pop     rax

    cmp     rdi, rax
    setg    al
    and     al, 1
    movzx   rax, al
    mov     rdi, rax
    call    stack_push

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; less than
;
;   INPUT: (int, int)
